if !(IsFeatureImplemented(FEAT_AA32) && IsFeatureImplemented(FEAT_ECV)) then
    Undefined();
elsif PSTATE.EL == EL0 then
    if IsFeatureImplemented(FEAT_AA64EL1) && !ELUsingAArch32(EL1) && EffectivelyAtEL0NotInHost() && CNTKCTL_EL1().EL0PCTEN == '0' then
        AArch64_AArch32SystemAccessTraptoEL1orEL2(0x04);
    elsif IsFeatureImplemented(FEAT_AA32EL1) && ELUsingAArch32(EL1) && CNTKCTL().PL0PCTEN == '0' then
        if EL2Enabled() && (IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2)) && HCR_EL2().TGE == '1' then
            AArch64_AArch32SystemAccessTrap(EL2, 0x04);
        elsif EL2Enabled() && (IsFeatureImplemented(FEAT_AA32EL2) && ELUsingAArch32(EL2)) && HCR().TGE == '1' then
            AArch32_TakeHypTrapException(0x00);
        else
            Undefined();
        end;
    elsif EL2Enabled() && (IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2)) && !ELIsInHost(EL2) && CNTHCTL_EL2().EL1PCTEN == '0' then
        AArch64_AArch32SystemAccessTrap(EL2, 0x04);
    elsif ELIsInHost(EL2) && (IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2)) && EffectiveTGEforEL0Traps() == '0' && CNTHCTL_EL2().EL1PCTEN == '0' then
        AArch64_AArch32SystemAccessTrap(EL2, 0x04);
    elsif EffectivelyAtEL0InHost() && (IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2)) && CNTHCTL_EL2().EL0PCTEN == '0' then
        AArch64_AArch32SystemAccessTrap(EL2, 0x04);
    elsif EL2Enabled() && (IsFeatureImplemented(FEAT_AA32EL2) && ELUsingAArch32(EL2)) && CNTHCTL().PL1PCTEN == '0' then
        AArch32_TakeHypTrapException(0x04);
    else
        if IsFeatureImplemented(FEAT_ECV_POFF) && EL2Enabled() && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) && (!HaveEL(EL3) || SCR_EL3().ECVEn == '1') && CNTHCTL_EL2().ECV == '1' && EffectivelyAtEL0NotInHost() then
            R(t, t2) = PhysicalCountInt() - CNTPOFF_EL2();
        else
            R(t, t2) = PhysicalCountInt();
        end;
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) && CNTHCTL_EL2().EL1PCTEN == '0' then
        AArch64_AArch32SystemAccessTrap(EL2, 0x04);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_AA32EL2) && ELUsingAArch32(EL2) && CNTHCTL().PL1PCTEN == '0' then
        AArch32_TakeHypTrapException(0x04);
    else
        if IsFeatureImplemented(FEAT_ECV_POFF) && EL2Enabled() && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) && (!HaveEL(EL3) || SCR_EL3().ECVEn == '1') && CNTHCTL_EL2().ECV == '1' then
            R(t, t2) = PhysicalCountInt() - CNTPOFF_EL2();
        else
            R(t, t2) = PhysicalCountInt();
        end;
    end;
elsif PSTATE.EL == EL2 then
    R(t, t2) = PhysicalCountInt();
elsif PSTATE.EL == EL3 then
    R(t, t2) = PhysicalCountInt();
end;
